function addTwoNumbers(l1, l2) {
  const toNumber = (node) => {
    let num = 0n, place = 1n;
    for (; node !== null; node = node.next) {
      num += BigInt(node.val) * place;   // ones digit comes first
      place *= 10n;
    }
    return num;
  };
  const digits = String(toNumber(l1) + toNumber(l2));
  const dummy = new ListNode(0);
  let tail = dummy;
  for (let i = digits.length - 1; i >= 0; i--) {   // back to ones-first order
    tail.next = new ListNode(Number(digits[i]));
    tail = tail.next;
  }
  return dummy.next;
}

class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        String digits = toNumber(l1).add(toNumber(l2)).toString();
        ListNode dummy = new ListNode(0), tail = dummy;
        for (int i = digits.length() - 1; i >= 0; i--) {   // back to ones-first order
            tail.next = new ListNode(digits.charAt(i) - '0');
            tail = tail.next;
        }
        return dummy.next;
    }

    private java.math.BigInteger toNumber(ListNode node) {
        StringBuilder sb = new StringBuilder();
        for (; node != null; node = node.next) sb.append(node.val);
        return new java.math.BigInteger(sb.reverse().toString());   // ones digit came first
    }
}

class Solution {
public:
    // C++ has no built-in big integer: this only works while the sum fits in 64 bits.
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        unsigned long long sum = toNumber(l1) + toNumber(l2);
        ListNode dummy(0);
        ListNode* tail = &dummy;
        do {
            tail->next = new ListNode(sum % 10);   // ones digit first
            tail = tail->next;
            sum /= 10;
        } while (sum > 0);
        return dummy.next;
    }

private:
    unsigned long long toNumber(ListNode* node) {
        unsigned long long num = 0, place = 1;
        for (; node != nullptr; node = node->next) {
            num += node->val * place;
            place *= 10;
        }
        return num;
    }
};

